import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures the font is ready before frame 0
const { fontFamily: interFamily } = loadInter();



export type PopUpListProps = Record<string, any>;

const PopUpList: React.FC<PopUpListProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  items = ["Risk", "Structure", "Discipline"],
  textColor = "#ffffff",
  accentColor = "#0066ff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive size calculations
  const s = Math.min(width, height);
  const fontSize = s * 0.085;
  const iconSize = s * 0.085;
  const itemGap = s * 0.03;
  const listGap = s * 0.05;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: `${listGap}px`,
          alignItems: "flex-start", // Left aligns the column content internally
        }}
      >
        {items.map((item, index) => {
          // Stagger each item by 12 frames
          const itemSpring = spring({
            frame: frame - index * 12,
            fps,
            config: { damping: 14, stiffness: 120 },
          });

          const opacity = interpolate(itemSpring, [0, 1], [0, 1], {
            extrapolateRight: "clamp",
          });
          const translateY = interpolate(itemSpring, [0, 1], [60, 0]);
          const scale = interpolate(itemSpring, [0, 1], [0.8, 1]);

          // Animate the checkmark to pop in slightly after its text starts moving
          const checkmarkSpring = spring({
            frame: frame - index * 12 - 6,
            fps,
            config: { damping: 10, stiffness: 150 }, // Bouncier configuration
          });
          const checkmarkScale = interpolate(checkmarkSpring, [0, 1], [0, 1]);
          const checkmarkRotation = interpolate(checkmarkSpring, [0, 1], [-45, 0]);

          return (
            <div
              key={index}
              style={{
                display: "flex",
                alignItems: "center",
                gap: `${itemGap}px`,
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                transition: "none",
              }}
            >
              {/* Checkmark Container */}
              <div
                style={{
                  width: `${iconSize}px`,
                  height: `${iconSize}px`,
                  borderRadius: `${iconSize / 2}px`,
                  backgroundColor: accentColor,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${checkmarkScale}) rotate(${checkmarkRotation}deg)`,
                  transition: "none",
                  flexShrink: 0,
                }}
              >
                <svg
                  width={iconSize * 0.6}
                  height={iconSize * 0.6}
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="#ffffff"
                  strokeWidth="3.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              </div>

              {/* Text Item */}
              <span
                style={{
                  fontSize: `${fontSize}px`,
                  fontWeight: 800,
                  color: textColor,
                  textTransform: "uppercase",
                  letterSpacing: `${s * 0.005}px`,
                  lineHeight: 1,
                  transition: "none",
                }}
              >
                {item}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default PopUpList;